typedef float rational_t;

void *operator new(unsigned, unsigned, const char *, int);
int nglGetScreenWidth();

class stringx
{
public:
  struct buffer { int refs; int alloc; int char_length; };
  buffer *my_buf;

  stringx();
  stringx(int);
  stringx(const stringx &);
  ~stringx();
  const char *c_str() const;
  void make_room(int);
  void append(const stringx &);
};

inline stringx operator+(const stringx &lhs, const stringx &rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

class widget
{
public:
  enum rhw_layer_e { RHW0 };
  static rational_t rhw_2d_val[];
  static rational_t rhw_layer_ranges[][2];
  static rhw_layer_e rhw_2d_layer;
  static rhw_layer_e last_rhw_2d_layer;

  widget(const char *, widget *, short, short);
  virtual ~widget();

  static void set_rhw_2d_layer(rhw_layer_e layer)
  {
    last_rhw_2d_layer = rhw_2d_layer;
    rhw_2d_layer = layer;
    rhw_2d_val[rhw_2d_layer] = rhw_layer_ranges[rhw_2d_layer][0];
  }

  static void restore_last_rhw_2d_layer()
  {
    rhw_2d_layer = last_rhw_2d_layer;
  }

private:
  char data[0x140];
};

class bitmap_widget : public widget
{
public:
  bitmap_widget(const char *, widget *, short, short, int);
  void open(const char *);
  void resize(rational_t, rational_t);

private:
  char data[0x174];
};

class background_widget : public widget
{
public:
  background_widget(const char *, widget *, short, short, const stringx &);
};

#define NEW new(0, __PRETTY_FUNCTION__, 0)

background_widget::background_widget( const char *_widget_name, widget *_parent, short _x, short _y, const stringx &file_prefix )
  : widget( _widget_name, _parent, _x, _y )
{
  const int wu = nglGetScreenWidth() / 5;
  const int hu = 256;

  const int tw[] = { wu, 2*wu, 2*wu, wu, 2*wu, 2*wu };
  const int tx[] = { 0,    wu, 3*wu,  0,   wu, 3*wu };
  const int ty[] = { 0,     0,    0, hu,   hu,   hu };

  for ( int i = 0; i < 6; ++i )
  {
    widget::set_rhw_2d_layer( widget::RHW0 );
    bitmap_widget *bitmap = NEW bitmap_widget( "bg", this, tx[i], ty[i], 1 );
    stringx filename = file_prefix + stringx(i);
    bitmap->open( filename.c_str() );
    bitmap->resize( tw[i], hu );
    widget::restore_last_rhw_2d_layer();
  }
}
